    if (ihl < sizeof(*ip) || data + sizeof(*eth) + ihl > data_end)
        return XDP_PASS;

    struct tcphdr *tcp = data + sizeof(*eth) + ihl;
    if (data + sizeof(*eth) + ihl + sizeof(*tcp) > data_end)
        return XDP_PASS;

