	__u64 packets;	/* total packets seen in this flow */
	__u64 bytes;	/* total bytes seen in this flow */
	__u32 syn_seen;	/* 1 if SYN flag observed */
	__u32 fin_seen;	/* 1 if FIN flag observed */
	__u32 rst_seen;	/* 1 if RST flag observed */
};

